Method.Source:
/// <summary>
/// Loads an instance of the <c>PrintMgmtPrintSettingDetail</c> class used to print a report.
/// </summary>
/// <param name="_settingDetail">
/// An instance of the <c>PrintMgmtPrintSettingDetail</c> class.
/// </param>
/// <param name="_documentKeyValue">
/// A human readable value that uniquely identifies the document to be printed.
/// </param>
/// <remarks>
/// Either this method or the <c>load</c> method must be called before other instance methods.
/// </remarks>
public void avaAddOrCreateSettingDetail(PrintMgmtPrintSettingDetail _settingDetail, str _documentKeyValue = '')
{
    if (!printSetting)
    {
        printSetting = new PrintMgmtPrintSetting();
    }
    printSetting.addPrintDetail(_settingDetail);
    documentKeyValue = _documentKeyValue;
    this.reset();
}
